import { CitationBlurb } from './CitationBlurb'
@Component
export struct ArticleTile {
 @Prop body: string = ''
 @Prop citation: string = ''
 build() {
  Column() {
   Text(this.body).fontSize(18)
   CitationBlurb({ content: this.citation })
  }
 }
}

@Component
export struct CitationBlurb {
 @Prop content: string = ''
 build() {
  Row() { Text(this.content).fontSize(11) }
 }
}

